spec.setup_code:
var geometry = new api.THREE.BoxGeometry(1, 1, 1);
                var material = new api.THREE.MeshPhongMaterial({ color: 0xE8593C });
                var cube = new api.THREE.Mesh(geometry, material);
                api.group.add(cube);
                return {
                  update: function(t) {
                    cube.rotation.x = t * 0.02;
                    cube.rotation.y = t * 0.03;
                  }
                };

return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var startX = W * 0.25, startY = H * 0.75;
                    var legLen = Math.min(W, H) * 0.35;
                    var period = 240;
                    var progress = (t % period) / period;
                    var totalPath = legLen * 2;
                    var dist = progress * totalPath;
                    var px, py;
                    if (dist <= legLen) {
                      px = startX;
                      py = startY - dist;
                    } else {
                      px = startX + (dist - legLen);
                      py = startY - legLen;
                    }
                    ctx.strokeStyle = '#E8593C';
                    ctx.lineWidth = 4;
                    ctx.beginPath();
                    ctx.moveTo(startX, startY);
                    if (dist <= legLen) {
                      ctx.lineTo(px, py);
                    } else {
                      ctx.lineTo(startX, startY - legLen);
                      ctx.lineTo(px, py);
                    }
                    ctx.stroke();
                    ctx.strokeStyle = '#4A90D9';
                    ctx.setLineDash([6, 6]);
                    ctx.beginPath();
                    ctx.moveTo(startX, startY);
                    ctx.lineTo(px, py);
                    ctx.stroke();
                    ctx.setLineDash([]);
                    ctx.fillStyle = '#E8593C';
                    ctx.beginPath();
                    ctx.arc(px, py, 8, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.fillStyle = '#333333';
                    ctx.beginPath();
                    ctx.arc(startX, startY, 5, 0, Math.PI * 2);
                    ctx.fill();
                    var pxPerMeter = legLen / 100;
                    var distMeters = dist / pxPerMeter;
                    var dxM = (px - startX) / pxPerMeter;
                    var dyM = (startY - py) / pxPerMeter;
                    var dispMeters = Math.sqrt(dxM * dxM + dyM * dyM);
                    ctx.fillStyle = '#E8593C';
                    ctx.font = '16px sans-serif';
                    ctx.fillText('Distance: ' + distMeters.toFixed(0) + ' m', 20, 30);
                    ctx.fillStyle = '#4A90D9';
                    ctx.fillText('Displacement: ' + dispMeters.toFixed(0) + ' m', 20, 55);
                  }
                };
